using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "InfusionPactAction", menuName = "Data/Battle/Battle Actions/Orion/InfusionPact Action")]
public class InfusionPactAction : MultiStarAction
{
	public override void CastAmount(int amount, GameObject source)
	{
		if (starAbilityReference.Value == knowledgeOrbStarAbility)
		{
			GetBattleAction().Cast(source);
			CheckMoveOrb(source);
		}
	}
}
